<?php $id=(int)($_GET['id']??0);$k=mysqli_fetch_assoc(mysqli_query($koneksi,"SELECT * FROM kategori WHERE idkategori=$id"));$q=mysqli_query($koneksi,"SELECT * FROM alat WHERE idkategori=$id ORDER BY namaalat"); ?>
<section class="page-public"><div class="container"><a class="back-link" href="index.php?halaman=daftarkategori"><i class="fas fa-arrow-left mr-1"></i>Kembali ke kategori</a><div class="public-page-heading mt-3"><div><span class="eyebrow">KATEGORI</span><h1><?=htmlspecialchars($k['namakategori']??'Kategori')?></h1><p>Daftar sarana yang masuk ke kategori ini.</p></div></div><div class="row"><?php while($r=mysqli_fetch_assoc($q)): ?><div class="col-md-6 col-lg-4 mb-4"><div class="tool-card compact"><div class="tool-icon"><?php $fn=basename((string)($r['foto']??'')); $nm=strtolower((string)$r['namaalat']); if($fn===''||$fn==='default.png'||!is_file(__DIR__.'/../../assets/uploads/sarana/'.$fn)){ $fn='toolbox_set.jpg'; foreach(['laptop'=>'laptop_asus.jpg','komputer'=>'laptop_asus.jpg','proyektor'=>'proyektor_epson.jpg','kabel'=>'kabel_hdmi.jpg','hdmi'=>'kabel_hdmi.jpg','mouse'=>'mouse_wireless.jpg','kamera'=>'kamera.jpg'] as $kw=>$im){if(strpos($nm,$kw)!==false){$fn=$im;break;}} } ?><img src="assets/uploads/sarana/<?=htmlspecialchars($fn,ENT_QUOTES,'UTF-8')?>" alt="Foto <?=htmlspecialchars($r['namaalat'],ENT_QUOTES,'UTF-8')?>" style="width:100%;height:100%;object-fit:cover;border-radius:12px" loading="lazy"></div><div class="tool-content"><h3><?=htmlspecialchars($r['namaalat'])?></h3><div class="tool-meta"><span><i class="fas fa-box"></i> <?=$r['jumlah']?> unit</span><span><i class="fas fa-map-marker-alt"></i> <?=htmlspecialchars($r['lokasi'])?></span></div></div></div></div><?php endwhile; ?></div></div></section>